import path from "node:path";

import { isSafeRepositoryPath } from "@mokly/viewer/data";

import { isInside } from "../config/paths.js";
import type { ResolvedConfig } from "../config/types.js";
import type { GitCommandRunner } from "../review/git.js";
import { GitProcessError } from "../review/git_process.js";

import { generatedSource } from "./ownership.js";

/** Read ownership proofs from the index; local generated files may be stale or absent. */
export async function trackedOwnedOutput(
  runner: GitCommandRunner,
  config: ResolvedConfig,
  prefixes: readonly string[],
): Promise<readonly string[]> {
  let matches: string;
  try {
    matches = await runner.run([
      "grep",
      "--cached",
      "--full-name",
      "--no-color",
      "-n",
      "-z",
      "-I",
      "-m",
      "1",
      "-e",
      "^<!-- Generated by mokly",
      "-e",
      "^<!-- Generated by mokabook",
      "--",
      ...prefixes.map((prefix) => `:(top,literal)${prefix}`),
    ]);
  } catch (error) {
    if (error instanceof GitProcessError && error.exitCode === 1) return [];
    throw error;
  }
  const owned: string[] = [];
  let start = 0;
  while (start < matches.length) {
    const fileEnd = matches.indexOf("\0", start);
    const numberEnd = matches.indexOf("\0", fileEnd + 1);
    const lineEnd = matches.indexOf("\n", numberEnd + 1);
    if (fileEnd < start || numberEnd < 0 || lineEnd < 0)
      throw new Error("Git returned invalid indexed ownership matches");
    const file = matches.slice(start, fileEnd);
    const line = matches.slice(fileEnd + 1, numberEnd);
    const source = generatedSource(matches.slice(numberEnd + 1, lineEnd + 1));
    if (
      line === "1" &&
      file.endsWith(".html") &&
      source &&
      isSafeRepositoryPath(source) &&
      isInside(config.entriesDir, path.resolve(config.repoRoot, source))
    )
      owned.push(file);
    start = lineEnd + 1;
  }
  return owned;
}
